let searchTimer;
function liveSearch(e){const id=e.target.id;if(!['shop-query','school-query','venue-query'].includes(id)||e.isComposing)return;const value=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(id==='shop-query'){shopQuery=value;shopLimit=36;pages.shop=0;}else if(id==='school-query'){schoolQuery=value;pages.schools=0;}else{venueQuery=value;venueLimit=12;pages.venues=0;}const focused=document.activeElement?.id===id;render();if(focused){const input=$(id);input?.focus();input?.setSelectionRange?.(value.length,value.length);}},260);}
root.addEventListener('input',liveSearch);
